var items = document.querySelectorAll('.rank-item, .rank-list .item, li.rank-item');
if (!items.length) items = document.querySelectorAll('[class*="rank-item"], [class*="video-card"]');
var list = [];
items.forEach(function(el, i) {
  var titleEl = el.querySelector('.title, .info a, [class*="title"]');
  var linkEl = el.querySelector('a[href*="/video/"]') || (titleEl && titleEl.closest('a'));
  var playEl = el.querySelector('[class*="play"], [class*="view"], .detail-state .data-box');
  var authorEl = el.querySelector('[class*="author"], [class*="up-name"], .detail-state .data-box:nth-child(2)');
  if (titleEl) {
    var href = linkEl ? linkEl.href : '';
    list.push({
      rank: i + 1,
      title: titleEl.textContent.trim(),
      url: href,
      play: playEl ? playEl.textContent.trim() : '',
      author: authorEl ? authorEl.textContent.trim() : ''
    });
  }
});
return JSON.stringify(list);

var items = document.querySelectorAll('[class*="HotItem"]');
if (!items.length) items = document.querySelectorAll('.HotList-item');
if (!items.length) items = document.querySelectorAll('section a[href*="/question/"]');
var list = [];
items.forEach(function(el, i) {
  var titleEl = el.querySelector('[class*="HotItem-title"], .HotList-itemTitle, h2');
  var metricEl = el.querySelector('[class*="HotItem-metrics"], .HotList-itemMetrics');
  var linkEl = el.closest('a') || el.querySelector('a');
  if (titleEl) {
    list.push({
      rank: i + 1,
      title: titleEl.textContent.trim(),
      heat: metricEl ? metricEl.textContent.trim() : '',
      url: linkEl ? linkEl.href : '',
    });
  }
});
return JSON.stringify(list);

var resp = await fetch('https://weibo.com/ajax/side/hotSearch');
if (!resp.ok) {
  return JSON.stringify([]);
}
var json = await resp.json();
var realtime = (json.data && json.data.realtime) || [];
return JSON.stringify(realtime.slice(0, 30).map(function(v, i) {
  return {
    rank: i + 1,
    title: v.note || v.word,
    heat: v.num,
    category: v.category || '',
    url: 'https://s.weibo.com/weibo?q=' + encodeURIComponent('#' + (v.note || v.word) + '#')
  };
}));

var items = document.querySelectorAll('li.topic-top-item, [class*="topic-item"], .topic-list li');
var list = [];
items.forEach(function(el, i) {
  var titleEl = el.querySelector('a.topic-text, [class*="topic-text"], a');
  var numEl = el.querySelector('span.topic-num, [class*="topic-num"]');
  var descEl = el.querySelector('p.topic-top-item-desc, [class*="desc"]');
  if (titleEl && titleEl.textContent.trim()) {
    list.push({
      rank: i + 1,
      title: titleEl.textContent.trim(),
      discussions: numEl ? numEl.textContent.trim() : '',
      description: descEl ? descEl.textContent.trim() : '',
      url: titleEl.href || '',
    });
  }
});
return JSON.stringify(list);

const resp = await fetch('/r/popular.json?limit=25&raw_json=1');
const data = await resp.json();
const posts = data.data.children;
return JSON.stringify(posts.map((p, i) => ({
  rank: i + 1,
  title: p.data.title,
  subreddit: p.data.subreddit,
  score: p.data.score,
  comments: p.data.num_comments,
  url: 'https://www.reddit.com' + p.data.permalink,
})));

var items = document.querySelectorAll('[class*="hot-list"] li, [class*="HotBoardList"] li, .trending-item');
if (!items.length) items = document.querySelectorAll('ul li a[href*="/hot/"]');
var list = [];
items.forEach(function(el, i) {
  var titleEl = el.querySelector('[class*="title"], span, a');
  var hotEl = el.querySelector('[class*="hot"], [class*="count"]');
  if (titleEl && titleEl.textContent.trim()) {
    list.push({
      rank: i + 1,
      title: titleEl.textContent.trim(),
      heat: hotEl ? hotEl.textContent.trim() : ''
    });
  }
});
return JSON.stringify(list);

var items = document.querySelectorAll('[class*="note-item"], [class*="feeds-page"] section, a[href*="/explore/"]');
if (!items.length) items = document.querySelectorAll('.note-item, section.note-item');
var list = [];
items.forEach(function(el, i) {
  var titleEl = el.querySelector('[class*="title"], .title, span');
  var authorEl = el.querySelector('[class*="author"], [class*="name"]');
  var likeEl = el.querySelector('[class*="like"], [class*="count"]');
  var linkEl = el.querySelector('a[href*="/explore/"], a[href*="/discovery/"]');
  if (titleEl && titleEl.textContent.trim()) {
    list.push({
      rank: i + 1,
      title: titleEl.textContent.trim(),
      author: authorEl ? authorEl.textContent.trim() : '',
      likes: likeEl ? likeEl.textContent.trim() : '',
      url: linkEl ? linkEl.href : '',
    });
  }
});
return JSON.stringify(list.slice(0, 30));

var items = document.querySelectorAll('[data-testid="trend"], [class*="trend"]');
var list = [];
items.forEach(function(el, i) {
  var spans = el.querySelectorAll('span');
  var title = '';
  var tweets = '';
  spans.forEach(function(s) {
    var txt = s.textContent.trim();
    if (txt.startsWith('#') || (txt.length > 2 && !txt.includes('Trending') && !txt.includes('posts'))) {
      if (!title) title = txt;
    }
    if (txt.includes('posts') || txt.includes('K') || txt.includes('M')) {
      tweets = txt;
    }
  });
  if (title) {
    list.push({ rank: i + 1, title: title, tweets: tweets });
  }
});
return JSON.stringify(list.slice(0, 30));

var items = document.querySelectorAll('[data-testid="feedItem"], [data-testid="postThreadItem"]');
var list = [];
items.forEach(function(el, i) {
  var author = el.querySelector('[data-testid="profileHeaderDisplayName"], [class*="displayName"]');
  var text = el.querySelector('[data-testid="postText"], [class*="postText"]');
  var likes = el.querySelector('[data-testid="likeCount"], [aria-label*="like"]');
  if (text && list.length < 20) list.push({rank: list.length+1, author: author ? author.textContent.trim() : '', text: text.textContent.trim().substring(0, 200), likes: likes ? likes.textContent.trim() : ''});
});
return JSON.stringify(list);

(async function() {
  for (var i = 0; i < 20; i++) {
    var cards = document.querySelectorAll('[class*="MessageCard"], [class*="message-card"], [class*="feed-item"], [class*="feedItem"], article');
    if (cards.length > 2) break;
    await new Promise(function(r){setTimeout(r, 500);});
  }
  var items = document.querySelectorAll('[class*="MessageCard"], [class*="message-card"], [class*="feed-item"], [class*="feedItem"], article');
  var list = [];
  items.forEach(function(el) {
    var author = el.querySelector('[class*="username"], [class*="UserName"], [class*="displayName"], [class*="nickName"]');
    var text = el.querySelector('[class*="content"], [class*="text"], [class*="body"] p, p');
    if (text && list.length < 20) {
      var txt = text.textContent.replace(/\s+/g,' ').trim().substring(0, 200);
      if (txt.length > 5) list.push({rank: list.length+1, author: author ? author.textContent.trim() : '', text: txt});
    }
  });
  return list;
})()

var items = document.querySelectorAll('.main-content a, .box a');
var list = [];
items.forEach(function(el, i) {
  var t = el.querySelector('span, p');
  if (!t) t = el;
  var text = t.textContent.trim();
  if (text.length > 5 && text.length < 100 && el.href && list.length < 20) list.push({rank: list.length+1, title: text, url: el.href});
});
return JSON.stringify(list);

var items = document.querySelectorAll('[action-type="feed_list_item"], .card-wrap');
var list = [];
items.forEach(function(el, i) {
  var t = el.querySelector('[class*="txt"], p[node-type="feed_list_content"]');
  var a = el.querySelector('.name, [class*="name"]');
  if (t && list.length < 20) list.push({rank: list.length+1, content: t.textContent.trim().substring(0, 200), author: a ? a.textContent.trim() : ''});
});
return JSON.stringify(list);

var items = document.querySelectorAll('.SearchResult-Card, [class*="SearchItem"]');
var list = [];
items.forEach(function(el, i) {
  var t = el.querySelector('h2 a span, [class*="title"]');
  var link = el.querySelector('h2 a');
  var excerpt = el.querySelector('[class*="content"], [class*="RichText"]');
  if (t && list.length < 20) list.push({rank: list.length+1, title: t.textContent.trim(), url: link ? link.href : '', excerpt: excerpt ? excerpt.textContent.trim().substring(0, 150) : ''});
});
return JSON.stringify(list);

var links = document.querySelectorAll('a[href*="blog.sina.com.cn/s/blog_"]');
var results = [], seen = {};
links.forEach(function(a, idx) {
  var title = a.textContent.replace(/\s+/g,' ').trim();
  var href = a.getAttribute('href') || '';
  if (!title || title.length < 4 || seen[title]) return;
  seen[title] = true;
  results.push({rank: results.length+1, title: title, url: href});
});
if (results.length === 0) {
  document.querySelectorAll('.atc_title a, .SG_txtb a, .title a').forEach(function(a) {
    var title = a.textContent.replace(/\s+/g,' ').trim();
    var href = a.getAttribute('href') || '';
    if (title && title.length >= 4 && !seen[title]) {
      seen[title] = true;
      results.push({rank: results.length+1, title: title, url: href});
    }
  });
}
return results.slice(0, 20);
